function splitArguments(line: string): string[] | null {
    const argumentsList: string[] = [];
    let position = 0;
    while (position < line.length) {
        if (line[position] === ' ') { ++position; continue; }
        if (line[position] !== '"') {
            const start = position;
            while (position < line.length && line[position] !== ' ') ++position;
            argumentsList.push(line.slice(start, position));
            continue;
        }
    return argumentsList;
const commands = new Map<string, CommandSpec>();
function register(group: Group, names: string, minimum: number, maximum = minimum, parity: 0 | 1 | null = null): void {
    for (const name of names.split(' ')) commands.set(name, { group, minimum, maximum, parity });
}
