                    options.set(option, args[index]);
                } else options.set(option, '');
            }
            if ((options.has('NX') && options.has('XX')) || (options.has('EX') && options.has('KEEPTTL'))) fail(messages.syntax);
            let expiry: number | null = null;
            if (options.has('EX')) {
